<?phpif (!defined('BASEPATH')) exit('No direct script access allowed');class mfabricfinishwet_drymodel extends CI_Model {    function fnGetInfo($VarFabricFinish = '', $VarStatus = '', $VarId = '') {        $this->db->select('id,fabricfinish,processingtype,updatedby,status,datecreated,dateupdated'); // Select field        $this->db->from(KN_MASTER_FABRIC_FINISH_WET_DRY);        // if ($VarStatus <> '') {        //     $this->db->where_in('status', array($VarStatus));        // } else {        //     $this->db->where_in('status', array(1, 2));        // }        if ($VarId <> '') {            $ArrWhere['id'] = $VarId;        }        if ($VarFabricFinish <> '') {            $ArrWhere['fabricfinish'] = trim($VarFabricFinish);        }        if (@count($ArrWhere) >= 1) {            $this->db->where($ArrWhere);        }        $ArrResultList = $this->db->get()->result_array();        return $ArrResultList;    }    function fnCheck($VarData = '', $VarId = '') {        $this->db->from(KN_MASTER_FABRIC_FINISH_WET_DRY);        //$ArrWhere = array('status' => "1");        if ($VarId <> '') {            $this->db->where_not_in('id', array($VarId));        }        if ($VarData <> '') {            $ArrWhere['fabricfinish'] = trim($VarData);        }        $countAll = $this->db->where($ArrWhere)->count_all_results();        return $countAll;    }    function saveInfo($ArrUpdateData) {        $VarId = $ArrUpdateData['id'];        if ($VarId == "") {            $ArrCheckExist = $this->fnGetInfo($ArrUpdateData['fabricfinish'], 1);            if (empty($ArrCheckExist)) {                unset($ArrUpdateData['id']);                $this->db->insert(KN_MASTER_FABRIC_FINISH_WET_DRY, $ArrUpdateData);                $VarId = $this->db->insert_id();                $ArrResult['errcode'] = 1;                $ArrResult['msg'] = '';                $ArrResult['id'] = $VarId;                $ArrResult['eid'] = urlencode(base64_encode($VarId));            } else {                $ArrResult['errcode'] = -1;                $ArrResult['msg'] = "This fabric finishing process already exists";            }        } else {            $ArrCheckExist = $this->fnCheck($ArrUpdateData['fabricfinish'], $VarId);            if (empty($ArrCheckExist)) {                if ($this->db->update(KN_MASTER_FABRIC_FINISH_WET_DRY, $ArrUpdateData, array('id' => $VarId))) {                    $ArrResult['errcode'] = 1;                    $ArrResult['msg'] = '';                    $ArrResult['id'] = $VarId;                    $ArrResult['eid'] = urlencode(base64_encode($VarId));                } else {                    $ArrResult['errcode'] = -1;                    $ArrResult['msg'] = 'Invalid Data';                }            } else {                $ArrResult['errcode'] = -1;                $ArrResult['msg'] = "This fabric finishing process already exists";            }        }        return $ArrResult;    }    function fnCount($VarFf = '', $VarProcesingType = '', $VarStatus = '', $VarAfilter = '') {        $ArrUserLoggedInfo = fnGetUserLoggedInfo('1');        $VarCompanyId = $ArrUserLoggedInfo['companyid'];        $ArrWhere = array();        if ($VarFf <> '') {            $ArrWhere[] = "fabricfinish like '%" . $VarFf . "%'";        }        if ($VarProcesingType <> '') {            $ArrWhere[] = "processingtype like '%" . $VarProcesingType . "%'";        }        if ($VarStatus <> '') {            $ArrWhere[] = "ff.status=" . $VarStatus;        } else {            $ArrWhere[] = "ff.status in(1,2)";        }        if ($VarAfilter <> '') {            $ArrWhere[] = "fabricfinish like '" . $VarAfilter . "%'";        }        $VarWhere = '';        if (@$ArrWhere[0] <> '') {            $VarWhere = implode(" and ", $ArrWhere) . " AND ff.companyid = '" . $VarCompanyId . "' ";        }        $VarSqlLab = "SELECT count(1) as trec  FROM " . KN_MASTER_FABRIC_FINISH_WET_DRY . " AS ff LEFT JOIN " . KN_USERS . " AS u ON ff.updatedby = u.id WHERE " . $VarWhere;        $ObjRows = $this->db->query($VarSqlLab)->row();        return $ObjRows->trec;    }    function fnList($VarFf = '', $VarProcesingType = '', $VarStatus = '', $VarLimit = 10, $offset = 0, $VarSortBy, $VarSortOrder, $VarAfilter = '') {        $ArrUserLoggedInfo = fnGetUserLoggedInfo('1');        $VarCompanyId = $ArrUserLoggedInfo['companyid'];        $VarSortOrder = ($VarSortOrder == 'desc') ? 'desc' : 'asc';        $VarSortCols = array('fabricfinish', 'processingtype', 'ff.status', 'u.contactname', 'ff.dateupdated');        $VarSortBy = (in_array($VarSortBy, $VarSortCols)) ? $VarSortBy : 'ff.dateupdated';        $VarLimitInfo = $VarLimit;        if ($offset >= 1) {            $VarLimitInfo = $offset . "," . $VarLimit;        }        $ArrWhere = array();        if ($VarFf <> '') {            $ArrWhere[] = "fabricfinish like '%" . $VarFf . "%'";        }        if ($VarProcesingType <> '') {            $ArrWhere[] = "processingtype like '%" . $VarProcesingType . "%'";        }        if ($VarStatus <> '') {            $ArrWhere[] = "ff.status=" . $VarStatus;        } else {            $ArrWhere[] = "ff.status in(1,2)";        }        if ($VarAfilter <> '') {            $ArrWhere[] = "fabricfinish like '" . $VarAfilter . "%'";        }        $VarWhere = '';        if (@$ArrWhere[0] <> '') {            $VarWhere = implode(" and ", $ArrWhere) . " AND ff.companyid = '" . $VarCompanyId . "'";        }        //removed this line . " limit " . $VarLimitInfo in below query        $VarSqlLab = "SELECT ff.id,fabricfinish,processingtype,u.contactname,ff.dateupdated,ff.status FROM " . KN_MASTER_FABRIC_FINISH_WET_DRY . " AS ff LEFT JOIN " . KN_USERS . " AS u ON ff.updatedby = u.id WHERE " . $VarWhere . " order by " . $VarSortBy . " " . $VarSortOrder;        $ObjResult = $this->db->query($VarSqlLab);        return $ObjResult;    }    function fnChangeStat($checkboxids, $optvalue) {        $Arrids = json_decode($checkboxids, true);        $this->db->where_in('id', $Arrids);        if ($this->db->update(KN_MASTER_FABRIC_FINISH_WET_DRY, array('status' => $optvalue))) {            return true;        }        return false;    }}